const syncAssetRelations = `-- name: SyncAssetRelations :exec
INSERT INTO asset_relations (workspace_id, from_id, to_id, kind, origin)
SELECT DISTINCT $1::uuid, a.id, b.id, l.kind, 'discovered'
FROM asset_source_links l
JOIN assets a ON a.workspace_id = $1 AND a.source_kind = l.from_kind AND a.source_ref = l.from_ref
JOIN assets b ON b.workspace_id = $1 AND b.source_kind = l.to_kind AND b.source_ref = l.to_ref
WHERE a.id <> b.id
ON CONFLICT (from_id, to_id, kind) DO NOTHING
`

func (q *Queries) SyncAssetRelations(ctx context.Context, workspaceID uuid.UUID) error {
	_, err := q.db.Exec(ctx, syncAssetRelations, workspaceID)
	return err
}

const syncAssetSources = `-- name: SyncAssetSources :many

INSERT INTO assets (workspace_id, kind, name, source_kind, source_ref, facts, last_seen_at, created_by_name, updated_by_name)
SELECT s.workspace_id, s.kind, left(s.name, 200), s.kind, s.ref, s.facts, now(), 'Morche', 'Morche'
FROM asset_sources s WHERE s.workspace_id = $1
ON CONFLICT (workspace_id, source_kind, source_ref) WHERE source_kind <> ''
DO UPDATE SET name = EXCLUDED.name, facts = EXCLUDED.facts, last_seen_at = now(), source_gone = false
RETURNING id, (xmax = 0)::bool AS inserted, source_gone
`

type SyncAssetSourcesRow struct {
	ID         uuid.UUID `json:"id"`
	Inserted   bool      `json:"inserted"`
	SourceGone bool      `json:"source_gone"`
}

// ---- Sync with what Morche manages ----
// Adds a linked asset for each server, database, storage… of the workspace
// that has none yet and refreshes the facts of the rest. inserted = new.
func (q *Queries) SyncAssetSources(ctx context.Context, workspaceID uuid.UUID) ([]SyncAssetSourcesRow, error) {
	rows, err := q.db.Query(ctx, syncAssetSources, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SyncAssetSourcesRow{}
	for rows.Next() {
		var i SyncAssetSourcesRow
		if err := rows.Scan(&i.ID, &i.Inserted, &i.SourceGone); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

