const upsertAssetSettings = `-- name: UpsertAssetSettings :one
INSERT INTO asset_settings (workspace_id, auto_discover, discover_hours, remind_days, channel_ids, notify_owners)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (workspace_id) DO UPDATE SET
    auto_discover = EXCLUDED.auto_discover, discover_hours = EXCLUDED.discover_hours,
    remind_days = EXCLUDED.remind_days, channel_ids = EXCLUDED.channel_ids,
    notify_owners = EXCLUDED.notify_owners, updated_at = now()
RETURNING workspace_id, auto_discover, discover_hours, remind_days, channel_ids, notify_owners, last_discovery_at, updated_at
`

type UpsertAssetSettingsParams struct {
	WorkspaceID   uuid.UUID   `json:"workspace_id"`
	AutoDiscover  bool        `json:"auto_discover"`
	DiscoverHours int32       `json:"discover_hours"`
	RemindDays    []int32     `json:"remind_days"`
	ChannelIds    []uuid.UUID `json:"channel_ids"`
	NotifyOwners  bool        `json:"notify_owners"`
}

func (q *Queries) UpsertAssetSettings(ctx context.Context, arg UpsertAssetSettingsParams) (AssetSetting, error) {
	row := q.db.QueryRow(ctx, upsertAssetSettings,
		arg.WorkspaceID,
		arg.AutoDiscover,
		arg.DiscoverHours,
		arg.RemindDays,
		arg.ChannelIds,
		arg.NotifyOwners,
	)
	var i AssetSetting
	err := row.Scan(
		&i.WorkspaceID,
		&i.AutoDiscover,
		&i.DiscoverHours,
		&i.RemindDays,
		&i.ChannelIds,
		&i.NotifyOwners,
		&i.LastDiscoveryAt,
		&i.UpdatedAt,
	)
	return i, err
}
